input.command:
cd /home/runner/work/PlayGround/PlayGround && node -e "
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const m = html.match(/<script>([\s\S]*?)<\/script>/);
if (!m) { console.log('NO SCRIPT FOUND'); process.exit(1); }
try { new Function(m[1]); console.log('JS OK — script parses, length', m[1].length, 'chars'); }
catch (e) { console.log('SYNTAX ERROR:', e.message); process.exit(1); }
"
